<style>
    .kms-ann-page{max-width:1180px;margin:0 auto}.kms-ann-head{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:22px}.kms-ann-eyebrow{margin:0 0 5px;color:#1a5d3a;font-size:11px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}.kms-ann-title{margin:0;color:#143f2b;font-size:28px;line-height:1.15;font-weight:800}.kms-ann-subtitle{margin:7px 0 0;color:#718078;font-size:13px;line-height:1.55}.kms-ann-add,.kms-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:42px;padding:0 16px;border-radius:10px;border:0;text-decoration:none;font-size:12px;font-weight:800;cursor:pointer}.kms-ann-add,.kms-btn-primary{background:#1a5d3a;color:#fff}.kms-ann-add:hover,.kms-btn-primary:hover{background:#154a2e}.kms-ann-add svg{width:16px;height:16px}.kms-btn-secondary{background:#fff;color:#355c47;border:1px solid #d9e3dc}.kms-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:18px}.kms-stat{padding:15px 17px;border:1px solid #e0e7e2;border-radius:14px;background:#fff}.kms-stat small{display:block;color:#819087;font-size:10px;font-weight:700}.kms-stat strong{display:block;margin-top:4px;color:#184d32;font-size:23px}.kms-table-card,.kms-form-card{overflow:hidden;border:1px solid #e0e7e2;border-radius:16px;background:#fff;box-shadow:0 6px 18px rgba(30,75,49,.035)}.kms-table-wrap{overflow-x:auto}.kms-table{width:100%;border-collapse:collapse;min-width:880px}.kms-table th{padding:12px 14px;background:#f5f8f5;color:#66756c;font-size:10px;text-align:left;text-transform:uppercase;letter-spacing:.04em}.kms-table td{padding:15px 14px;border-top:1px solid #edf1ee;vertical-align:top;color:#4f6056;font-size:12px}.kms-row-title{margin:0;color:#183f2d;font-size:13px;font-weight:800}.kms-row-content{margin:5px 0 0;max-width:430px;color:#7a8780;font-size:11px;line-height:1.5}.kms-badge{display:inline-flex;align-items:center;justify-content:center;min-height:24px;padding:0 9px;border-radius:999px;font-size:10px;font-weight:800;white-space:nowrap}.kms-badge-info{background:#eef5ff;color:#315f9c}.kms-badge-important{background:#fff5d8;color:#8a5a00}.kms-badge-urgent{background:#feecec;color:#b42318}.kms-badge-active{background:#e8f6ec;color:#17713b}.kms-badge-scheduled{background:#eef1ff;color:#4b55a1}.kms-badge-ended,.kms-badge-off{background:#f1f3f2;color:#747e78}.kms-pin{display:inline-flex;margin-top:6px;color:#1a5d3a;font-size:10px;font-weight:800}.kms-actions-inline{display:flex;justify-content:flex-end;gap:7px;flex-wrap:wrap}.kms-link{display:inline-flex;align-items:center;justify-content:center;min-height:32px;padding:0 10px;border:1px solid transparent;border-radius:8px;background:#fff;font-size:10px;font-weight:800;text-decoration:none;cursor:pointer}.kms-link-view{color:#17643b;border-color:#cfe1d4}.kms-link-edit{color:#846100;border-color:#eadcae}.kms-link-delete{color:#b42318;border-color:#f1c7c4}.kms-alert{margin-bottom:16px;padding:13px 15px;border-radius:11px;font-size:12px;line-height:1.55}.kms-alert-success{background:#eaf7ee;border:1px solid #cfe8d6;color:#17643b}.kms-alert-error{background:#fff0ef;border:1px solid #f0cbc7;color:#a72b23}.kms-alert ul{margin:7px 0 0 18px}.kms-form-card{padding:22px}.kms-form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.kms-field-full{grid-column:1/-1}.kms-label{display:block;margin-bottom:7px;color:#2d4e3a;font-size:11px;font-weight:800}.kms-input,.kms-select,.kms-textarea{width:100%;border:1px solid #dbe4de;border-radius:10px;background:#fff;color:#243b2e;font:inherit;font-size:13px;outline:none;transition:border-color .2s,box-shadow .2s}.kms-input,.kms-select{height:44px;padding:0 12px}.kms-textarea{min-height:180px;padding:12px;resize:vertical;line-height:1.6}.kms-input:focus,.kms-select:focus,.kms-textarea:focus{border-color:#62a37a;box-shadow:0 0 0 3px rgba(26,93,58,.08)}.kms-help{margin:6px 0 0;color:#89938d;font-size:10px;line-height:1.5}.kms-toggle-row{displa